-- 453_hidden_curated.sql — #453 Orlando story batch: 11 HIDDEN storyless OSM pins brought back with a story (drafted 2026-11-04).
-- Same shape and rules as 452_hidden_curated.sql: exact stored name at the stored coordinate, read from the stored places:v34
-- rows on 2026-11-04; every pin passed #542 by pin id (its containing tile stores it); no same-name pin or gem within 2 km
-- (#519 (1)); no same-article Wikipedia pin within 300 m. One comes from the list sort (OR045: the Wells'Built hotel IS the
-- hidden museum pin, 68 m from the article point); ten from the gate-drops union (453_gate_drops_orlando.tsv, verdict RESCUED).
-- Six See Art Orlando pieces share one source (the program's unveiling-night description of each sculpture); "Discovery Muse"
-- and "Menello Museum of American Folk Art" are OSM's spellings — the row must carry the stored name to meet its pin.
-- Batch file — run in the Mac session after the seed commit, then curated_category_backfill(true); each row should report
-- dist_m 0. Expect 11 returned names; "Success. No rows returned" means the guard skipped (already run — FROM RIVERSIDE (7)).
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Well's Built Museum of African American History & Culture$t$, 28.5385366::double precision, -81.3853979::double precision, $t$Dr. William Monroe Wells, one of Orlando's first Black doctors, built this hotel in 1921 for African Americans barred from Florida's segregated hotels, and with his nearby South Street Casino it hosted touring stars such as Ella Fitzgerald, Count Basie, Ray Charles and Louis Armstrong; the hotel has housed a museum of African American history since 2009.$t$, $t$https://en.wikipedia.org/wiki/Wells%27Built_Museum$t$, $t$#453 hidden-pin row: osm_way400479603, stored in 571_-1627, 571_-1628; containing tile 571_-1628 stores it (#542)$t$),
  ($t$Union$t$, 28.5455806::double precision, -81.370207::double precision, $t$Ralfonso Gschwend's Union, one of the eight privately funded See Art Orlando sculptures, is six 25-foot poles topped with thirty curved wings that turn and cross one another in the slightest breeze, so it never looks the same twice.$t$, $t$https://bungalower.com/2013/11/18/photo-tour-see-art-orlando-sculptures-unveiled-tonight/$t$, $t$#453 hidden-pin row: osm_node5586711218, stored in 571_-1627, 571_-1628; containing tile 571_-1627 stores it (#542)$t$),
  ($t$Take Flight$t$, 28.5454442::double precision, -81.3729462::double precision, $t$Douwe Blumberg's Take Flight, one of the eight privately funded See Art Orlando sculptures, is a flock of birds cast in alloy and welded together, rising into the sky from the water's edge of Lake Eola.$t$, $t$https://bungalower.com/2013/11/18/photo-tour-see-art-orlando-sculptures-unveiled-tonight/$t$, $t$#453 hidden-pin row: osm_node5586711219, stored in 571_-1627, 571_-1628; containing tile 571_-1627 stores it (#542)$t$),
  ($t$Centered$t$, 28.5423522::double precision, -81.373492::double precision, $t$C.J. Rench's Centered, one of the eight privately funded See Art Orlando sculptures, balances eight arching forms of different widths and colors around a yellow center that spins in the wind, a nod to Orlando's sunny weather, so it seems to change shape from every angle.$t$, $t$https://bungalower.com/2013/11/18/photo-tour-see-art-orlando-sculptures-unveiled-tonight/$t$, $t$#453 hidden-pin row: osm_node5586711220, stored in 571_-1627, 571_-1628; containing tile 571_-1627 stores it (#542)$t$),
  ($t$Discovery Muse$t$, 28.5444396::double precision, -81.3753919::double precision, $t$Meg White's Muse of Discovery, one of the eight privately funded See Art Orlando sculptures, is a reclining woman of earthwork and limestone gazing at her open hand, which is big enough for a child or an adult to sit in.$t$, $t$https://bungalower.com/2013/11/18/photo-tour-see-art-orlando-sculptures-unveiled-tonight/$t$, $t$#453 hidden-pin row: osm_node10895921807, stored in 571_-1628; containing tile 571_-1628 stores it (#542)$t$),
  ($t$Global Convergence$t$, 28.5424732::double precision, -81.3776238::double precision, $t$Deedee Morrison's Global Convergence, one of the eight privately funded See Art Orlando sculptures, is a 12-foot globe of cut aluminum panels whose patterns show a school of shoal bass swimming in blue light from LEDs inside.$t$, $t$https://bungalower.com/2013/11/18/photo-tour-see-art-orlando-sculptures-unveiled-tonight/$t$, $t$#453 hidden-pin row: osm_way1382648560, stored in 571_-1627, 571_-1628; containing tile 571_-1628 stores it (#542)$t$),
  ($t$Tower of Light$t$, 28.5382036::double precision, -81.3789935::double precision, $t$A fixture in front of City Hall since 1992, this sculpture, nicknamed "the asparagus" by many, went unlit after 1993 until the Orlando Chapter of Commercial Real Estate Women raised more than $52,000 to restore it alongside eight new public art pieces downtown.$t$, $t$https://mynews13.com/fl/orlando/news/2013/11/12/tower_of_light_turne$t$, $t$#453 hidden-pin row: osm_way1382446202, stored in 571_-1627, 571_-1628; containing tile 571_-1628 stores it (#542)$t$),
  ($t$Menello Museum of American Folk Art$t$, 28.5700011::double precision, -81.3673192::double precision, $t$Housed in Howard Phillips' former house on Lake Formosa, the Mennello Museum of American Art opened in 1998 around a collection of paintings by Earl Cunningham given by Marilyn and Michael Mennello of Winter Park, and its grounds hold a sculpture garden of abstract works by Alice Aycock.$t$, $t$https://en.wikipedia.org/wiki/Mennello_Museum_of_American_Art$t$, $t$#453 hidden-pin row: osm_way375858329, stored in 571_-1627, 571_-1628, 572_-1627; containing tile 571_-1627 stores it (#542)$t$),
  ($t$Orlando Fire Museum$t$, 28.5730323::double precision, -81.3673455::double precision, $t$This two-story red brick firehouse served College Park as Orlando's Firehouse 3 on Orlando Avenue near Dade Street from 1926 to 1978, before it was moved here to Loch Haven Park and turned into the city's fire museum, which in 2016 was renamed for retired Deputy Fire Chief Randall R. Tuten.$t$, $t$https://www.gottagoorlando.com/post/celebrate-the-centennial-anniversary-of-orlando-firehouse-3-at-the-orlando-fire-museum$t$, $t$#453 hidden-pin row: osm_way550757263, stored in 571_-1627, 571_-1628, 572_-1627; containing tile 571_-1627 stores it (#542)$t$),
  ($t$Red Tails Memorial$t$, 28.5721892::double precision, -81.3677694::double precision, $t$Since 2013 this 12-foot bronze spire, rising to four P-51 Mustangs in the missing man formation, has honored the Tuskegee Airmen's Red Tail pilots, nicknamed for the red paint on their planes' tails and propellers; it was funded by Syd Levy of United Trophy.$t$, $t$https://www.osc.org/orlando-science-center-honors-red-tail-pilots/$t$, $t$#453 hidden-pin row: osm_node4639889178, stored in 571_-1627, 571_-1628, 572_-1627; containing tile 571_-1627 stores it (#542)$t$),
  ($t$The Lone Sailor$t$, 28.5750026::double precision, -81.3378389::double precision, $t$Dedicated on April 2, 2016, this bronze Lone Sailor stands at the edge of the old parade field of Naval Training Center Orlando, commissioned in 1968, whose Recruit Training Command became the first coeducational training center in the U.S. military before the land was redeveloped as Baldwin Park.$t$, $t$https://dvidshub.net/news/260291/one-sailor-stands-alone-lone-sailor-orlando$t$, $t$#453 hidden-pin row: osm_node12964848621, stored in 572_-1627; containing tile 572_-1627 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
